def swap_adjacent(values):
    out=values[:] 
    for i in range(0,len(out)-1,2):
        out[i],out[i+1]=out[i+1],out[i]
    return out

def distinct_letters(text):
    letters = set()
    for c in text:
        if "a" <= c <= "z" or "A" <= c <= "Z":
            letters.add(c.lower())
    return len(letters)

def last_even_index(values):
    idx=-1
    for i,x in enumerate(values):
        if x%2==0:idx=i
    return idx

def positive_product(values):
    result=1
    found=False
    for x in values:
        if x>0:
            result*=x
            found=True
    return result if found else 0
